 * @param {{platform?: string, arch?: string}} [options]
 * @returns {{name: string, url: string, arch: string}|null}
 */
export function pickAsset(assets, options = {}) {
  const platform = options.platform ?? process.platform;
  const arch = assetArch(options.arch ?? process.arch);
  const os = platform === "win32" ? "windows" : platform === "darwin" ? "darwin" : platform === "linux" ? "linux" : "";
  if (os === "") return null;
  const prefix = `mihomo-${os}-${arch}`;
  const scored = [];
  for (const asset of Array.isArray(assets) ? assets : []) {
    const name = typeof asset?.name === "string" ? asset.name : "";
    if (!name.toLowerCase().endsWith(".zip")) continue;
    if (!name.startsWith(prefix)) continue;
    if (/-go\d+-/.test(name)) continue;
    let score = 0;
    if (name.includes("-compatible")) score = 1;
    else if (/-amd64-v[23]/.test(name)) score = 2;
    else score = 0;
    scored.push({ name, url: asset.browser_download_url ?? `${ASSET_HOST}/`, arch, score });
  }
  scored.sort((a, b) => a.score - b.score || a.name.localeCompare(b.name));
  const best = scored[0];
  return best === undefined ? null : { name: best.name, url: best.url, arch: best.arch };
}

